import org.jetbrains.exposed.v1.dao.ULongEntityClass
import org.jetbrains.exposed.v1.core.dao.id.EntityID
import org.junit.jupiter.api.Test


/**
 * Defines an input value for a test case, which specifies values for data points
 * required by the workflow or step being tested. Inputs can be user-defined or
 * generated by an AI model.
 */
class TestInputRepoTest : ULongIdGenericRepoTest<TestInputEntity>() {

    override fun mockEntity(): TestInputEntity = mockk(relaxed = true)

    override fun mockEntityId(): EntityID<ULong> {
        val id = mockk<EntityID<ULong>>()
        return id
    }

    override fun mockNonExistentEntityId(): EntityID<ULong> {
        val id = mockk<EntityID<ULong>>()
        return id
    }

    override fun MockKMatcherScope.anyT(): TestInputEntity {
        return any<TestInputEntity>()
    }

    

}

